package com.portfolio.urlshortener.service;
import com.portfolio.urlshortener.dto.AuthDtos.*;import com.portfolio.urlshortener.entity.AppUser;import com.portfolio.urlshortener.exception.ApiException;import com.portfolio.urlshortener.repository.UserRepository;import com.portfolio.urlshortener.security.JwtService;import org.springframework.http.HttpStatus;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service public class AuthService {private final UserRepository users;private final PasswordEncoder encoder;private final JwtService jwt;public AuthService(UserRepository u,PasswordEncoder e,JwtService j){users=u;encoder=e;jwt=j;}
 @Transactional public AuthResponse register(RegisterRequest r){String email=r.email().trim().toLowerCase();if(users.existsByEmail(email))throw new ApiException(HttpStatus.CONFLICT,"Email is already registered");AppUser u=users.save(new AppUser(email,encoder.encode(r.password())));return response(u);}
 public AuthResponse login(LoginRequest r){AppUser u=users.findByEmail(r.email().trim().toLowerCase()).orElseThrow(()->new ApiException(HttpStatus.UNAUTHORIZED,"Invalid email or password"));if(!encoder.matches(r.password(),u.getPasswordHash()))throw new ApiException(HttpStatus.UNAUTHORIZED,"Invalid email or password");return response(u);}private AuthResponse response(AppUser u){return new AuthResponse(jwt.generate(u.getEmail()),"Bearer",jwt.getTtl(),u.getEmail());}
}
